OPJ_BOOL write_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    if (!p_j2k || !p_data || !p_data_written || !p_manager) {
        OPJ_UNUSED(p_stream);
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Invalid arguments to write_sot_marker\n");
        return OPJ_FALSE;
    }

    /* JPEG 2000 SOT marker is 0xFF91 followed by the length (2 bytes), and the tile part index (1 byte). */
    if (p_total_data_size < 4) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Insufficient buffer size to write SOT marker\n");
        return OPJ_FALSE;
    }

    p_data[0] = (OPJ_BYTE)(0xFF);
    p_data[1] = (OPJ_BYTE)(0x91);
    p_data[2] = 0x00; /* Length MSB */
    p_data[3] = 0x01; /* Length LSB, 1 byte for tile part index, assuming only tile part A is written here. */

    *p_data_written = 4;

    return OPJ_TRUE;
}

OPJ_BOOL write_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    (void)p_stream;  // Mark as unused

    if (!p_j2k || !p_data || !p_data_written || !p_manager) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Invalid parameters for writing SOT marker.\n");
        return OPJ_FALSE;
    }

    if (p_total_data_size < 12) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Insufficient buffer size to write SOT marker.\n");
        return OPJ_FALSE;
    }

    /* Write SOT marker (0xFF91) */
    p_data[0] = 0xFF;
    p_data[1] = 0x91;

    /* Length of SOT segment (4 bytes) */
    p_data[2] = (OPJ_BYTE)((p_j2k->sot_length >> 8) & 0xFF);
    p_data[3] = (OPJ_BYTE)(p_j2k->sot_length & 0xFF);

    /* Tile number (2 bytes) */
    p_data[4] = (OPJ_BYTE)((p_j2k->tile_number >> 8) & 0xFF);
    p_data[5] = (OPJ_BYTE)(p_j2k->tile_number & 0xFF);

    /* Number of layers (2 bytes) */
    p_data[6] = (OPJ_BYTE)((p_j2k->num_layers >> 8) & 0xFF);
    p_data[7] = (OPJ_BYTE)(p_j2k->num_layers & 0xFF);

    /* Number of resolution levels (1 byte) */
    p_data[8] = p_j2k->num_resolution_levels;

    /* Number of components (1 byte) */
    p_data[9] = p_j2k->num_components;

    /* Progression order (1 byte) */
    p_data[10] = p_j2k->progression_order;

    /* Data length (1 byte) */
    p_data[11] = p_j2k->data_length;

    *p_data_written = 12;

    return OPJ_TRUE;
}

OPJ_BOOL write_j2k_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    OPJ_UINT32 sot_length = 12; /* SOT marker is 12 bytes long (marker code + length + parameters) */

    if (!p_j2k || !p_data || !p_data_written) {
        opj_event_msg(p_manager, OPJ_EVT_ERROR, "Invalid parameters for writing SOT marker.\n");
        return OPJ_FALSE;
    }

    if (p_total_data_size < sot_length) {
        opj_event_msg(p_manager, OPJ_EVT_ERROR, "Output buffer too small to write SOT marker.\n");
        return OPJ_FALSE;
    }

    /* Write SOT marker code (0xFF91) */
    p_data[0] = 0xFF;
    p_data[1] = 0x91;

    /* Write length (10 bytes for SOT marker) */
    p_data[2] = 0x00;
    p_data[3] = 0x0A;

    /* Write rest of the parameters (example placeholder values) */
    p_data[4] = 0x00; /* POC */
    p_data[5] = 0x00; /* POC */
    p_data[6] = 0x00; /* Tile index */
    p_data[7] = 0x00;
    p_data[8] = 0x00; /* Tile index */
    p_data[9] = 0x01;

    p_data[10] = 0x00; /* Reserved */
    p_data[11] = 0x00; /* Reserved */

    *p_data_written = sot_length;
    return OPJ_TRUE;
}

OPJ_BOOL write_SOT_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager)
{
    /* Check preconditions */
    if (!p_j2k || !p_data || !p_data_written || !p_manager) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Invalid parameters for writing SOT marker.\n");
        return OPJ_FALSE;
    }

    /* Check if there is enough space in the buffer for the SOT marker (minimum size) */
    if (*p_data_written + 11 > p_total_data_size) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Not enough space in the buffer to write the SOT marker.\n");
        return OPJ_FALSE;
    }

    /* Write the SOT marker (0xFF91) */
    p_data[(*p_data_written)++] = 0xFF;
    p_data[(*p_data_written)++] = 0x91;

    /* Write the length of the SOT marker segment (excluding the first two bytes) - 8 bytes */
    p_data[(*p_data_written)++] = 0x00;
    p_data[(*p_data_written)++] = 0x08;

    /* Write the tile index (0x0000 for the first tile) */
    p_data[(*p_data_written)++] = 0x00;
    p_data[(*p_data_written)++] = 0x00;

    /* Write the number of components (same as the image) */
    p_data[(*p_data_written)++] = (OPJ_BYTE)(p_j2k->image->numcomps >> 8);
    p_data[(*p_data_written)++] = (OPJ_BYTE)(p_j2k->image->numcomps & 0xFF);

    /* Write the progression order (0x0000 for default) */
    p_data[(*p_data_written)++] = 0x00;
    p_data[(*p_data_written)++] = 0x00;

    /* Write the number of layers (0x0001 for one layer) */
    p_data[(*p_data_written)++] = 0x00;
    p_data[(*p_data_written)++] = 0x01;

    return OPJ_TRUE;
}

OPJ_BOOL write_SOT_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    if (!p_j2k || !p_data || !p_data_written || !p_manager) {
        OPJ_UNUSED(p_stream);
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Invalid parameters for writing SOT marker.\n");
        return OPJ_FALSE;
    }

    if (p_total_data_size < 12) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Insufficient buffer space to write SOT marker.\n");
        return OPJ_FALSE;
    }

    /* Write SOT marker (0xFF9C) */
    p_data[0] = 0xFF;
    p_data[1] = 0x9C;

    /* Length of SOT marker (excluding the 2 bytes for the marker code), 10 bytes */
    p_data[2] = 0x00;
    p_data[3] = 0x0A;

    /* Tile index (assumed to be 0 for this example) */
    p_data[4] = 0x00;
    p_data[5] = 0x00;

    /* Length of the tile-part (excluding SOT marker, 8 bytes) */
    p_data[6] = 0x00;
    p_data[7] = 0x08;

    /* Number of resolution levels (assumed to be 1 for this example) */
    p_data[8] = 0x01;

    /* Progression order (assumed to be 0 for this example) */
    p_data[9] = 0x00;

    /* Reference grid size (assumed to be 0x0001 0x0001) */
    p_data[10] = 0x00;
    p_data[11] = 0x01;
    p_data[12] = 0x00;
    p_data[13] = 0x01;

    *p_data_written = 14;

    return OPJ_TRUE;
}
